import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Errors reference","description":"","frontmatter":{},"headers":[],"relativePath":"ERRORS.md","filePath":"ERRORS.md"}'),n={name:"ERRORS.md"};function r(o,e,d,h,l,c){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="errors-reference" tabindex="-1">Errors reference <a class="header-anchor" href="#errors-reference" aria-label="Permalink to &quot;Errors reference&quot;">​</a></h1><blockquote><p><a href="./ERRORS">🇬🇧 English</a> • <a href="./ERRORS.ja">🇯🇵 日本語</a></p></blockquote><p>This document is intended for users who want to inspect kiwa&#39;s error design. In v0.1.0, <code>packages/dapp/src/rpc-handlers.ts</code> throws errors with EIP-1193-compatible codes, and <code>packages/dapp/src/fixture.ts</code> converts them into the envelope returned to the page. The injector script unwraps that envelope and restores it into a form where page-side <code>catch</code> blocks can read <code>code</code>.</p><h2 id="official-eip-1193-error-codes" tabindex="-1">Official EIP-1193 error codes <a class="header-anchor" href="#official-eip-1193-error-codes" aria-label="Permalink to &quot;Official EIP-1193 error codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td><code>4001</code></td><td>User Rejected Request</td><td>User rejected</td></tr><tr><td><code>4100</code></td><td>Unauthorized</td><td>Operation does not match the active account</td></tr><tr><td><code>4200</code></td><td>Unsupported Method</td><td>Method unsupported by the provider</td></tr><tr><td><code>4900</code></td><td>Disconnected</td><td>Provider disconnected</td></tr><tr><td><code>4901</code></td><td>Chain Disconnected</td><td>Disconnected from a specific chain</td></tr><tr><td><code>-32700</code></td><td>Parse error</td><td>Failed to parse the JSON string</td></tr><tr><td><code>-32602</code></td><td>Invalid params</td><td>Invalid param type or format</td></tr><tr><td><code>-32603</code></td><td>Internal error</td><td>Internal failure or transport failure</td></tr></tbody></table><p>The main codes that kiwa actually uses in v0.1.0 are <code>4100</code> <code>4200</code> <code>-32700</code> <code>-32602</code> <code>-32603</code>. <code>4902</code>, which is often seen around EIP-1193, is also used in surrounding specs, but the current core does not emit it because it does not have a chain registration table.</p><h2 id="implementation-specific-error-code" tabindex="-1">Implementation-specific error code <a class="header-anchor" href="#implementation-specific-error-code" aria-label="Permalink to &quot;Implementation-specific error code&quot;">​</a></h2><p>This code is not part of the official EIP-1193 set but is used by this implementation.</p><table tabindex="0"><thead><tr><th>Code</th><th>Purpose</th></tr></thead><tbody><tr><td><code>3</code></td><td><code>eth_sendTransaction</code> transaction rejected (insufficient balance / revert / signer-related viem error)</td></tr></tbody></table><p>code <code>3</code> is produced in <code>packages/dapp/src/tx.ts</code>, where an error thrown by viem is caught and normalized into <code>Eip1193Error(3, &#39;transaction rejected: ...&#39;)</code>. Using <code>(e as { code?: number }).code === 3</code> in a page-side <code>catch</code> block lets you observe rejection during submission to anvil.</p><h2 id="main-conditions-in-kiwa" tabindex="-1">Main conditions in kiwa <a class="header-anchor" href="#main-conditions-in-kiwa" aria-label="Permalink to &quot;Main conditions in kiwa&quot;">​</a></h2><h3 id="_4100" tabindex="-1"><code>4100</code> <a class="header-anchor" href="#_4100" aria-label="Permalink to &quot;`4100`&quot;">​</a></h3><ul><li>The address in <code>personal_sign</code> does not match the active account</li><li>The signer address in <code>eth_signTypedData_v4</code> does not match</li><li><code>from</code> in <code>eth_sendTransaction</code> does not match</li></ul><h3 id="_4200" tabindex="-1"><code>4200</code> <a class="header-anchor" href="#_4200" aria-label="Permalink to &quot;`4200`&quot;">​</a></h3><ul><li><code>eth_subscribe</code></li><li><code>eth_unsubscribe</code></li><li><code>wallet_requestPermissions</code></li><li><code>wallet_getPermissions</code></li><li><code>eth_sign</code></li></ul><p>These are rejected immediately in core as blocked methods.</p><h2 id="blocked-methods-list-and-reasons" tabindex="-1"><code>BLOCKED_METHODS</code> list and reasons <a class="header-anchor" href="#blocked-methods-list-and-reasons" aria-label="Permalink to &quot;`BLOCKED_METHODS` list and reasons&quot;">​</a></h2><p><code>BLOCKED_METHODS</code> in <code>packages/dapp/src/rpc-handlers.ts</code> is the list used to explicitly reject wallet features that the fixture does not reproduce with <code>4200 (Unsupported Method)</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Reason it is blocked</th></tr></thead><tbody><tr><td><code>eth_subscribe</code></td><td>The injected provider assumes an HTTP bridge, so it cannot keep subscription ID allocation and ongoing push delivery</td></tr><tr><td><code>eth_unsubscribe</code></td><td>Because <code>eth_subscribe</code> is not implemented, there is no subscription state to cancel</td></tr><tr><td><code>wallet_requestPermissions</code></td><td>EIP-2255 permission scopes require state management across requests, but the HTTP path cannot retain that state. In the test fixture, approval UX is substituted with `setApprovalMode(&#39;approve&#39;</td></tr><tr><td><code>wallet_getPermissions</code></td><td>Because there is no internal permission registry, the wallet cannot generate permission descriptors to return consistently</td></tr><tr><td><code>eth_sign</code></td><td>Raw digest signing differs significantly across wallet implementations, so kiwa narrows the deterministic test surface to <code>personal_sign</code> / <code>eth_signTypedData_v4</code></td></tr></tbody></table><h3 id="_32700" tabindex="-1"><code>-32700</code> <a class="header-anchor" href="#_32700" aria-label="Permalink to &quot;`-32700`&quot;">​</a></h3><ul><li>The typed data string for <code>eth_signTypedData_v4</code> is broken as JSON</li></ul><h3 id="_32602" tabindex="-1"><code>-32602</code> <a class="header-anchor" href="#_32602" aria-label="Permalink to &quot;`-32602`&quot;">​</a></h3><ul><li>The message for <code>personal_sign</code> looks like hex but contains invalid characters</li><li>The message for <code>personal_sign</code> is not a string</li><li><code>wallet_switchEthereumChain</code> / <code>wallet_addEthereumChain</code> do not include <code>chainId</code></li><li><code>chainId</code> is not in <code>0x</code> format</li></ul><h3 id="_32603" tabindex="-1"><code>-32603</code> <a class="header-anchor" href="#_32603" aria-label="Permalink to &quot;`-32603`&quot;">​</a></h3><ul><li><code>eth_sendTransaction</code> or fallback RPC is called when no anvil port is available</li><li>HTTP connection to anvil fails</li><li>anvil returns a non-200 response or a non-JSON response</li><li>An exception without an EIP-1193 code occurs inside core</li></ul><h2 id="error-envelope" tabindex="-1">Error envelope <a class="header-anchor" href="#error-envelope" aria-label="Permalink to &quot;Error envelope&quot;">​</a></h2><p>The fixture does not throw directly to the page. It first repacks the result into a plain object.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Envelope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ok</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">error</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">message</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } };</span></span></code></pre></div><p>This envelope is built in <code>page.exposeFunction(&#39;__dappE2eRpc&#39;, ...)</code> in <code>packages/dapp/src/fixture.ts</code>. When <code>handleRpcRequest()</code> throws <code>Eip1193Error</code>, it keeps that <code>code</code> and <code>message</code>. For a normal <code>Error</code> or an unknown exception, it fills in <code>-32603</code> before returning.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> handleRpcRequest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, request);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ok: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, result };</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (e) {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> err</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ok: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    error: { code: err.code </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">??</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32603</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, message: err.message },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  };</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="how-code-is-preserved-across-the-page-boundary" tabindex="-1">How <code>code</code> is preserved across the page boundary <a class="header-anchor" href="#how-code-is-preserved-across-the-page-boundary" aria-label="Permalink to &quot;How `code` is preserved across the page boundary&quot;">​</a></h2><p>The injector script receives the result of <code>window.__dappE2eRpc(args)</code>. If <code>ok: false</code>, it creates a new <code>Error</code> and attaches <code>err.code = envelope.error.code</code>. It then throws inside the page, so <code>catch</code> around <code>window.ethereum.request()</code> can read <code>code</code>.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.ethereum.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ method: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;eth_subscribe&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, params: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;newHeads&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] });</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (e) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }).code);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>With this approach, even across Playwright <code>page.evaluate()</code>, you can write page-side assertions such as <code>err.code === 4200</code>. For a concrete example, see <code>T-E2E-007</code> in <a href="../examples/basic-connect/tests/connect.spec.ts">examples/basic-connect/tests/connect.spec.ts</a>.</p><h2 id="relationship-between-events-and-errors" tabindex="-1">Relationship between events and errors <a class="header-anchor" href="#relationship-between-events-and-errors" aria-label="Permalink to &quot;Relationship between events and errors&quot;">​</a></h2><p>The payload code of the <code>disconnect</code> event is not necessarily the same as the rejection code of a request. The helper <code>disconnect()</code> only sends <code>4900</code>, and it does not have a mechanism to automatically fail in-flight RPCs. If you need to reproduce post-disconnect behavior strictly, it is safer to write event triggering and request assertions separately.</p><p>If <code>waitForRpcIdle()</code> times out, it also uses <code>-32603</code> as an <code>Eip1193Error</code>. That failure comes from fixture control rather than the provider itself, so in tests it is practical to assert the timeout message as well.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://eips.ethereum.org/EIPS/eip-1193#provider-errors" target="_blank" rel="noreferrer">EIP-1193 provider errors</a></li><li><a href="./RPC">RPC.md</a></li><li><a href="./EVENTS">EVENTS.md</a></li><li><a href="../examples/basic-connect/tests/connect.spec.ts">examples/basic-connect/tests/connect.spec.ts</a></li></ul>',39)])])}const E=s(n,[["render",r]]);export{k as __pageData,E as default};
